(() => {
  const storageKey='academ.document-preferences.v2',form=document.querySelector('#documentPreferences'),upload=document.querySelector('#documentLogoFile'),button=document.querySelector('#uploadDocumentLogo'),preview=document.querySelector('#documentLogoPreview'),image=document.querySelector('#documentUploadedLogo'),info=document.querySelector('#voucherInformation'),feedback=document.querySelector('#documentSettingsFeedback');
  const state=new URLSearchParams(location.search).get('state');let logo=null,saved=null;
  try{saved=JSON.parse(localStorage.getItem(storageKey));if(!saved){const previous=JSON.parse(localStorage.getItem('academ.document-preferences.v1'));if(previous&&typeof previous==='object'){saved={...previous,logo:null};localStorage.setItem(storageKey,JSON.stringify(saved))}}localStorage.removeItem('academ.document-preferences.v1')}catch{}
  if(saved&&typeof saved==='object'){logo=/^data:image\/(bmp|x-ms-bmp);base64,/.test(saved.logo||'')?saved.logo:null;info.value=typeof saved.information==='string'?saved.information:'';for(const name of ['guestList','automaticMail']){const value=saved[name]==='no'?'no':'yes';form.querySelector(`[name=${name}][value=${value}]`).checked=true}}
  if(state==='empty'){logo=null;info.value='';form.querySelectorAll('input[value=yes]').forEach(x=>x.checked=true)}
  function renderLogo(){preview.hidden=!logo;image.hidden=!logo;if(logo)image.src=logo;else image.removeAttribute('src');button.textContent=logo?'Удалить логотип':'Загрузить логотип'}
  function message(text,kind=''){feedback.textContent=text;feedback.className=kind?`is-${kind}`:'';feedback.hidden=false}
  button.addEventListener('click',()=>{if(logo){logo=null;upload.value='';renderLogo();message('Логотип удалён. Нажмите «Сохранить», чтобы применить изменения.')}else upload.click()});
  upload.addEventListener('change',async()=>{const file=upload.files[0];if(!file)return;try{if(file.size>300*1024)throw Error('Размер файла не должен превышать 300 КБ');const buffer=await file.arrayBuffer(),view=new DataView(buffer);if(buffer.byteLength<26||view.getUint16(0,true)!==0x4d42)throw Error('Выберите изображение в формате BMP');const headerSize=view.getUint32(14,true),width=headerSize===12?view.getUint16(18,true):view.getInt32(18,true),height=Math.abs(headerSize===12?view.getUint16(20,true):view.getInt32(22,true));const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать файл'));reader.readAsDataURL(new Blob([buffer],{type:'image/bmp'}))});const test=new Image();test.src=data;await test.decode();logo=data;renderLogo();message(width===2244&&height===295?'Логотип загружен. Нажмите «Сохранить», чтобы применить изменения.':'Логотип загружен. Размер отличается от 2244 × 295 пикселей — при печати возможны искажения.',width===2244&&height===295?'':'warning')}catch(error){message(error.message||'Не удалось загрузить логотип','error')}finally{upload.value=''}});
  form.addEventListener('input',event=>{if(event.target!==upload)feedback.hidden=true});
  form.addEventListener('submit',event=>{event.preventDefault();const data={logo,information:info.value,guestList:form.elements.guestList.value,automaticMail:form.elements.automaticMail.value};try{localStorage.setItem(storageKey,JSON.stringify(data));message('Настройки сохранены')}catch{message('Не удалось сохранить настройки в браузере. Попробуйте уменьшить размер логотипа.','error')}});
  renderLogo();
})();
